assert.throws(() => findConflicts([B("a", "r", "2026-03-01T09:00:00Z", "2026-03-01T10:00:00")]), TypeError);   // no Z
assert.throws(() => findConflicts([B("a", "r", "2026-03-01T09:00:00.000Z", "2026-03-01T10:00:00Z")]), TypeError); // millis
assert.throws(() => findConflicts([B("a", "r", "2026-02-30T10:00:00Z", "2026-03-01T10:00:00Z")]), TypeError); // bad day
assert.throws(() => findConflicts([B("a", "r", "2026-13-01T00:00:00Z", "2026-13-02T00:00:00Z")]), TypeError); // bad month
