assert.throws(() => findConflicts([B("a", "r", "2026-03-01T09:00:00Z", null)]), TypeError);
assert.throws(() => findConflicts([null]), TypeError);
assert.throws(() => findConflicts([B("a", "r", "2026-02-29T00:00:00Z", "2026-03-01T00:00:00Z")]), TypeError); // 2026 not leap
assert.doesNotThrow(() => findConflicts([B("a", "r", "2024-02-29T00:00:00Z", "2024-03-01T00:00:00Z")])); // 2024 leap ok

// R2: end not after start -> RangeError; duplicate id -> TypeError
assert.throws(() => findConflicts([B("a", "r", "2026-03-01T10:00:00Z", "2026-03-01T10:00:00Z")]), RangeError);
assert.throws(() => findConflicts([B("a", "r", "2026-03-01T11:00:00Z", "2026-03-01T10:00:00Z")]), RangeError);
assert.throws(() => findConflicts([B("a", "r1", "2026-03-01T09:00:00Z", "2026-03-01T10:00:00Z"), B("a", "r2", "2026-03-01T09:00:00Z", "2026-03-01T10:00:00Z")]), TypeError);

